query GetProductsByCateId{
    products(
            filter: {
                static: {
                    categories: ["380"],
                    excluded:{
                      categories: []
                    }
                    province_id: 30,
                    stock: {
                       from: 0
                    },
                    company_stock_id: [46, 56, 152, 4920],
                   filter_price: {from:0to:134000000}

                },
                dynamic: {


                }
            },
            page: 2,
            size: 20,
            sort: [{view: desc}]
        )
    {
        general{
            product_id
            name
            attributes
            sku
            doc_quyen
            manufacturer
            url_key
            url_path
            categories{
                categoryId
                name
                uri
            }
            review{
                total_count
                average_rating
            }
        },
        filterable{
            allow_cart_types
            is_installment
            stock_available_id
            company_stock_id
            stock
            filter {
               id
               Label
            }
            is_parent
            price
            prices
            special_price
            promotion_information
            thumbnail
            promotion_pack
            sticker
            flash_sale_types
            is_new_arrival
            display_root_price
            display_price
            default_bundle_discount {
              pricing_summaries
            }
            promotion_info
            delivery_badge
        },
    }
}
